def format_bytes(n):
    if n < 1024:
        return str(n) + ' B'
    value = n / 1024
    units = ['KB', 'MB', 'GB']
    i = 0
    while value >= 1024 and i < 2:
        value /= 1024
        i += 1
    return '%.1f %s' % (value, units[i])
